import * as React from 'react';
import useTableFilters from 'hooks/useTableFilters';
import { CardContent, Grid, IconButton, InputAdornment, TextField, Tooltip, Fab } from '@mui/material';
// project imports
import MainCard from 'ui-component/cards/MainCard';
import { useDispatch, useSelector } from 'store';
import { geAllPermission } from 'store/slices/userList';
// assetss
import EditIcon from '@mui/icons-material/Edit';
import PrintIcon from '@mui/icons-material/PrintTwoTone';
import SearchIcon from '@mui/icons-material/Search';
import AddIcon from '@mui/icons-material/AddTwoTone';
import DynamicTable from 'views/commons/tables/DynamicTable';
import DeleteIcon from '@mui/icons-material/Delete';
import DeleteAlert from 'views/commons/alerts/deleteAlarts';
import useSnackbar from 'hooks/useSnackbar';
import GenericModelForm from 'views/commons/modelform/GenericModleForm';
import ApiRequest from 'utils/apiService';

const permissionFields = [
    { name: 'name', label: 'Permission Name', required: true },
    {
        name: 'permission_type',
        label: 'Permission Type',
        type: 'select',
        options: [
            { value: 'menu', label: 'Menus' },
            { value: 'action', label: 'Actions' }
        ],
        required: true
    },
    { name: 'label', label: 'Label', required: true }
];
const PermissionListView = () => {
    const dispatch = useDispatch();
    const [searchInput, setSearchInput] = React.useState('');
    const { entities, pagination } = useSelector((state) => state.usersList);
    const permissions = entities.permissions || [];
    const { total = 0, page = 0 } = pagination.permissions || {};
    const [open, setOpen] = React.useState(false);
    const [rowsPerPage, setRowsPerPage] = React.useState(5);
    const [loading, setLoading] = React.useState(true);
    const [deleteDialogOpen, setDeleteDialogOpen] = React.useState(false);
    const [selectedIds, setSelectedIds] = React.useState([]);
    const { showSnackbar } = useSnackbar();
    const [selected, setSelected] = React.useState([]);
    const { searchQuery, order, orderBy, handleSearch, handleRequestSort } = useTableFilters();
    const [editData, setEditData] = React.useState(null);

    const handleSearchInputChange = (event) => {
        const value = event.target.value;
        setSearchInput(value); // ✅ Updates input field instantly
        handleSearch(value); // ✅ Calls debounce function for API call
    };

    React.useEffect(() => {
        let timeoutLoading; // ✅ Timeout to delay loading indicator

        const fetchData = async () => {
            timeoutLoading = setTimeout(() => setLoading(true), 500); // ✅ Only show loading if API takes >500ms

            await dispatch(geAllPermission(rowsPerPage, page, searchQuery, orderBy, order));

            clearTimeout(timeoutLoading); // ✅ Prevent unnecessary loading flicker
            setLoading(false);
        };

        fetchData();

        return () => {
            clearTimeout(timeoutLoading); // ✅ Cleanup timeout if component unmounts
        };
    }, [dispatch, rowsPerPage, page, searchQuery, orderBy, order]);

    const handlePageChange = (event, newPage) => {
        dispatch(geAllPermission(rowsPerPage, newPage, searchQuery, orderBy, order));
    };

    const handleRowsPerPageChange = (event) => {
        const newRowsPerPage = parseInt(event.target.value, 10);
        setRowsPerPage(newRowsPerPage);
        dispatch(geAllPermission(newRowsPerPage, 0, searchQuery, orderBy, order));
    };

    const handleSortChange = (property) => {
        handleRequestSort(property, (updatedProperty, updatedOrder) => {
            // ✅ Wait for state update before calling API
            dispatch(geAllPermission(rowsPerPage, page, searchQuery, updatedProperty, updatedOrder));
        });
    };

    const handleEdit = (row) => {
        setEditData(row); // ✅ Store the selected row data
        setOpen(true); // ✅ Open modal
    };
    const handleSelectAllClick = (event) => {
        if (event.target.checked) {
            setSelected(permissions.map((row) => row.id)); // ✅ Select all IDs
        } else {
            setSelected([]); // ✅ Deselect all
        }
    };
    const handleRowClick = (event, id) => {
        setSelected((prevSelected) => {
            const selectedIndex = prevSelected.indexOf(id);
            let newSelected = [];

            if (selectedIndex === -1) {
                newSelected = [...prevSelected, id]; // ✅ Add selection
            } else {
                newSelected = prevSelected.filter((selectedId) => selectedId !== id); // ✅ Remove selection
            }

            return newSelected;
        });
    };

    const handleDelete = (selectedIds) => {
        if (selectedIds.length === 0) return;
        setSelectedIds(selectedIds);
        setDeleteDialogOpen(true);
    };

    const handleClickOpenDialog = () => {
        setOpen(true);
    };
    const handleCloseDialog = () => {
        setOpen(false);
        setEditData(null);
    };
    const handlePermissionSubmit = async (data, resetForm) => {
        setLoading(true);
        const url = editData ? `/users/permission/edit/${editData.id}` : '/users/permission/add';
        const method = editData ? 'PUT' : 'POST';
        const defaultMessage = editData ? 'Permission Update successfully!' : 'Permission Add successfully!';

        try {
            const response = await ApiRequest(method, url, data);
            showSnackbar(response.message || defaultMessage, 'success');
            dispatch(geAllPermission(rowsPerPage, page, searchQuery, orderBy, order));
            resetForm();
        } catch (error) {
            showSnackbar(error.message, 'error');
        } finally {
            setLoading(false);
            setOpen(false);
            setEditData(null);
        }
    };

    return (
        <MainCard content={false}>
            <CardContent>
                <Grid container justifyContent="space-between" alignItems="center" spacing={2}>
                    <Grid item xs={12} sm={6}>
                        <TextField
                            InputProps={{
                                startAdornment: (
                                    <InputAdornment position="start">
                                        <SearchIcon fontSize="small" />
                                    </InputAdornment>
                                )
                            }}
                            onChange={handleSearchInputChange}
                            placeholder="Search Name"
                            value={searchInput}
                            size="small"
                        />
                    </Grid>
                    <Grid item xs={12} sm={6} sx={{ textAlign: 'right' }}>
                        <Tooltip title="Print">
                            <IconButton size="large">
                                <PrintIcon />
                            </IconButton>
                        </Tooltip>
                        {/* product add & dialog */}
                        <Tooltip title="Add Permission">
                            <Fab
                                color="primary"
                                size="small"
                                onClick={handleClickOpenDialog}
                                sx={{ boxShadow: 'none', ml: 1, width: 32, height: 32, minHeight: 32 }}
                            >
                                <AddIcon fontSize="small" />
                            </Fab>
                        </Tooltip>
                        <GenericModelForm
                            open={open}
                            handleCloseDialog={handleCloseDialog}
                            position="center"
                            fields={permissionFields}
                            onSubmit={handlePermissionSubmit}
                            formLabel={editData ? 'Edit Permission' : 'Add Permission'}
                            editData={editData}
                        />
                    </Grid>
                </Grid>
            </CardContent>
            <DynamicTable
                columns={[
                    { id: 'id', label: 'ID', align: 'center', sortable: true },
                    { id: 'name', label: 'Permission', align: 'left', sortable: true },
                    { id: 'label', label: 'Name', align: 'center', sortable: true },
                    { id: 'permission_type', label: 'Permission Type', align: 'left', sortable: false },
                    { id: 'createdAt', label: 'Created At', align: 'right', sortable: true },
                    { id: 'updatedAt', label: 'Updated At', align: 'right', sortable: true }
                ]}
                data={permissions}
                total={total}
                page={page}
                rowsPerPage={rowsPerPage}
                onPageChange={handlePageChange}
                onRowsPerPageChange={handleRowsPerPageChange}
                order={order}
                orderBy={orderBy}
                onRequestSort={handleSortChange}
                selected={selected || []}
                onSelectAllClick={handleSelectAllClick} // ✅ Pass select all function
                onRowClick={handleRowClick} // ✅ Pass row selection function
                onDelete={handleDelete} // ✅ Pass delete function
                showCheckbox // ✅ Add this to show checkboxes
                renderActions={(row) => (
                    <>
                        <IconButton size="small" onClick={() => handleEdit(row)}>
                            <EditIcon />
                        </IconButton>
                        <IconButton disabled={selected.length > 0} size="small" onClick={() => handleDelete([row.id])}>
                            <DeleteIcon />
                        </IconButton>
                    </>
                )}
                loading={loading}
            />

            <DeleteAlert
                open={deleteDialogOpen}
                onClose={() => setDeleteDialogOpen(false)}
                selectedIds={selectedIds}
                endpoint="/users/delete-perimission"
                onDeleteSuccess={() => {
                    showSnackbar('permission updated successfully!', 'success');
                    dispatch(geAllPermission(rowsPerPage, page, searchQuery, orderBy, order)); // ✅ Refresh roles list
                    setDeleteDialogOpen(false);
                    setSelected([]);
                    setSelectedIds([]); // ✅ Clear selection after delete
                }}
                message="Are you sure you want to delete the selected permissions?"
            />
        </MainCard>
    );
};

export default PermissionListView;
